function authorize(principal, action, ownerId) {
  if (!principal) return { status: 401, reason: "not authenticated" };
  const isOwner = principal.userId === ownerId;
  const isAdmin = principal.roles.includes("admin");
  if (action === "read") return { status: 200, reason: "ok" };
  if (action === "update") {
    return isOwner ? { status: 200, reason: "ok" } : { status: 403, reason: "forbidden: owner only" };
  }
  if (action === "delete") {
    return (isOwner || isAdmin) ? { status: 200, reason: "ok" } : { status: 403, reason: "forbidden: not owner or admin" };
  }
  return { status: 403, reason: "forbidden: unknown action" };
}
const cases = [
  { principal: null, action: "delete", ownerId: "u1" },
  { principal: { userId: "u2", roles: [] }, action: "read", ownerId: "u1" },
  { principal: { userId: "u2", roles: [] }, action: "update", ownerId: "u1" },
  { principal: { userId: "u1", roles: [] }, action: "update", ownerId: "u1" },
  { principal: { userId: "u9", roles: ["admin"] }, action: "update", ownerId: "u1" },
  { principal: { userId: "u9", roles: ["admin"] }, action: "delete", ownerId: "u1" },
  { principal: { userId: "u2", roles: [] }, action: "delete", ownerId: "u1" },
];
for (const c of cases) {
  const d = authorize(c.principal, c.action, c.ownerId);
  console.log(c.action, d.status, d.reason);
}

