function verifyToken(claims, now, denylist) {
  if (now >= claims.exp) return { ok: false, reason: "expired" };
  if (denylist.has(claims.jti)) return { ok: false, reason: "revoked" };
  return { ok: true, userId: claims.sub };
}
const denylist = new Set();
const token = { sub: "u1", jti: "jwt_A", exp: 100 };
console.log("t=50 fresh:", verifyToken(token, 50, denylist).ok);
denylist.add("jwt_A");
const r = verifyToken(token, 60, denylist);
console.log("t=60 after revoke:", r.ok, "-", r.reason);
const r2 = verifyToken(token, 150, denylist);
console.log("t=150 expired:", r2.ok, "-", r2.reason);

