const granted = new Set();
function confirmGrant(session, authUserId) {
  if (session.payment_status !== "paid") return { grant: false, reason: "not paid (" + session.payment_status + ")" };
  if (session.customer_ref !== authUserId) return { grant: false, reason: "session belongs to another user" };
