function auditKey(key, location) {
  if (key.startsWith("pk_")) return "ok";
  if (key.startsWith("sk_")) return location === "client" ? "CRITICAL: secret key in client" : "ok";
  if (key.startsWith("whsec_")) return location === "client" ? "CRITICAL: webhook secret in client" : "ok";
  if (key.startsWith("rk_")) return location === "client" ? "WARN: restricted key in client" : "ok";
  return "WARN: unknown key prefix";
}
