reconciling-state.code:
function applyOrdered(state, event, lastTs) {
  if (event.created < lastTs) return { state, lastTs, applied: false };
  let next = state;
  switch (event.type) {
    case "checkout.session.completed":
    case "invoice.payment_succeeded": next = "active"; break;
    case "invoice.payment_failed": next = "past_due"; break;
    case "customer.subscription.deleted": next = "canceled"; break;
    default: next = state;
  }
  return { state: next, lastTs: event.created, applied: true };
}
const events = [
  { type: "checkout.session.completed", created: 1 },
  { type: "invoice.payment_failed", created: 3 },
  { type: "invoice.payment_succeeded", created: 2 },
  { type: "customer.subscription.deleted", created: 4 },
];
let state = "none", lastTs = 0;
for (const e of events) {
  const r = applyOrdered(state, e, lastTs);
  state = r.state; lastTs = r.lastTs;
  console.log(e.type, "(t=" + e.created + ")", "->", r.applied ? state : "ignored (stale)");
}

