const DAY = 86400;
function hasAccess(status, periodEnd, graceDays, now) {
  if (status === "active" || status === "trialing") return true;
  if (status === "past_due") return now <= periodEnd + graceDays * DAY;
  return false;
}
const rows = [
  { status: "trialing", periodEnd: 100, grace: 3, now: 50 },
  { status: "active", periodEnd: 100, grace: 3, now: 999999 },
  { status: "past_due", periodEnd: 100, grace: 3, now: 100 + 2 * DAY },
  { status: "past_due", periodEnd: 100, grace: 3, now: 100 + 4 * DAY },
  { status: "canceled", periodEnd: 100, grace: 3, now: 50 },
];
for (const r of rows) {
  console.log(r.status, "@now=" + r.now, "->", hasAccess(r.status, r.periodEnd, r.grace, r.now) ? "grant" : "block");
}

