function openPortal(authCustomerId, returnUrl, allowedHosts) {
  if (!authCustomerId) return { error: "no authenticated customer" };
  if (!returnUrl) return { error: "return_url required" };
  let host;
  try { host = new URL(returnUrl).host; } catch { return { error: "return_url is not a valid URL" }; }
  if (!allowedHosts.includes(host)) return { error: "return_url host not allowed" };
  return { customer: authCustomerId, return_url: returnUrl };
}
const allowed = ["app.example.com"];
