function settleNow(oldCents, newCents, daysLeft, daysInPeriod) {
  const remaining = daysLeft / daysInPeriod;
  const oldValue = Math.round(oldCents * remaining);
  const newValue = Math.round(newCents * remaining);
  if (newCents > oldCents) return { netNow: newValue - oldValue, deferredCredit: 0 };
  if (newCents < oldCents) return { netNow: 0, deferredCredit: oldValue - newValue };
  return { netNow: 0, deferredCredit: 0 };
}
const up = settleNow(1000, 3000, 15, 30);
console.log("upgrade netNow/deferred:", up.netNow, up.deferredCredit);
const down = settleNow(3000, 1000, 15, 30);
console.log("downgrade netNow/deferred:", down.netNow, down.deferredCredit);
const lateral = settleNow(2000, 2000, 15, 30);
console.log("lateral netNow/deferred:", lateral.netNow, lateral.deferredCredit);

