function runDunningNotices(attempts, maxRetries, terminal) {
  let state = "past_due", used = 0, emails = 1; // initial dunning notice
  for (const a of attempts) {
    if (used >= maxRetries) break;
    used++;
    if (a === "success") { state = "active"; break; }
    emails++; // retry-failed notice
  }
  if (state === "past_due" && used >= maxRetries) { state = terminal; emails++; } // final notice
  return { state, retriesUsed: used, emailsSent: emails };
}
console.log("recovers:", JSON.stringify(runDunningNotices(["failure", "success"], 3, "canceled")));
console.log("exhausted:", JSON.stringify(runDunningNotices(["failure", "failure", "failure"], 3, "canceled")));
console.log("late recover:", JSON.stringify(runDunningNotices(["failure", "failure", "success"], 3, "unpaid")));

