function redactSensitive(payload) {
  const findings = [];
  const safe = {};
  for (const [k, v] of Object.entries(payload)) {
    const digits = typeof v === "string" ? v.replace(/[\s-]/g, "") : "";
    if (/card|pan|number|cc/i.test(k) && /^\d{13,19}$/.test(digits)) {
      findings.push("raw PAN in " + k);
      safe[k] = "****" + digits.slice(-4);
    } else if (/cvc|cvv|cid/i.test(k)) {
      findings.push("CVC stored in " + k);
      safe[k] = "***";
    } else {
      safe[k] = v;
    }
  }
  return { findings, safe };
}
const good = redactSensitive({ payment_method: "pm_123", customer: "cus_456" });
console.log("safe findings:", JSON.stringify(good.findings));
const bad = redactSensitive({ card_number: "4242 4242 4242 4242", cvc: "123" });
console.log("unsafe findings:", JSON.stringify(bad.findings));
console.log("redacted card:", bad.safe.card_number, "cvc:", bad.safe.cvc);

