function applyRefunds(chargeCents, requests) {
  let refunded = 0;
  const results = [];
  for (const req of requests) {
    if (req <= 0) { results.push("rejected: non-positive"); continue; }
    if (refunded + req > chargeCents) {
      results.push("rejected: exceeds remaining (" + (chargeCents - refunded) + " left)");
      continue;
    }
    refunded += req;
    results.push("ok: refunded " + req);
  }
  return { results, refunded };
}
const out = applyRefunds(5000, [2000, 2000, 2000]);
for (const r of out.results) console.log(r);
console.log("total refunded:", out.refunded);
